نقش سازمانی: مدیر خرید و تدارکات (procurement_manager)

درخواست کاربر:
لاستیک شاول را از کدام تأمین‌کننده بخریم؟ (مدیر خرید — مجتمع مس سرچشمه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "contracts",
      "description": "قراردادهای خرید: قیمت، حجم، مدت",
      "dimensions": [
        "supplier",
        "item"
      ],
      "measures": [
        "volume",
        "price_per_unit",
        "start_date",
        "end_date"
      ]
    },
    {
      "dataset": "inventory_critical",
      "description": "موجودی قطعات حیاتی و نقطهٔ سفارش",
      "dimensions": [
        "item"
      ],
      "measures": [
        "current_stock",
        "reorder_point",
        "lead_time_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "روز از سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "item"
      ]
    },
    {
      "metric": "critical_stockout_risk",
      "description": "ریسک کمبود قطعات حیاتی",
      "formula": "موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "item"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "contracts",
    "filters": {
      "item": "لاستیک شاول"
    }
  }
}

TOOL_OBSERVATION:
{
  "supplier_A": {
    "price": 2400,
    "lead_time": 24
  },
  "supplier_B": {
    "price": 2103.8450569272604,
    "lead_time": 44
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "inventory_critical",
    "filters": {
      "item": "لاستیک شاول"
    }
  }
}

TOOL_OBSERVATION:
{
  "current_stock_days": 21,
  "reorder_point_days": 30
}

نقش سازمانی: مدیر خرید و تدارکات (procurement_manager)

درخواست کاربر:
انحراف قیمت خرید 8.7% شده در حالی که ماه قبل 1.5% بود. چه اتفاقی افتاده؟ (مدیر خرید — شرکت سنگ‌آهن گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارشات خرید به تفکیک تأمین‌کننده و قلم",
      "dimensions": [
        "supplier",
        "item",
        "period"
      ],
      "measures": [
        "quantity",
        "unit_price",
        "total_cost"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "purchase_price_variance",
      "description": "انحراف قیمت خرید",
      "formula": "(قیمت واقعی - قیمت برنامه‌ریزی‌شده) / قیمت برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "item"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "purchase_price_variance"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "ppv": {
    "prev_month": 1.5,
    "curr_month": 8.7,
    "change": 7.2
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "purchase_orders",
    "filters": {
      "period": "curr_month",
      "ppv_above_zero": true
    }
  }
}

TOOL_OBSERVATION:
{
  "top_overpriced": [
    {
      "item": "لاستیک شاول",
      "ppv": 14.1
    },
    {
      "item": "روغن هیدرولیک",
      "ppv": 13.2
    }
  ]
}

