پیش‌بینی قیمت خرید مواد اولیه برای سه ماه آینده را می‌خواهم. (مدیر خرید)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "contracts",
      "description": "قراردادهای خرید: قیمت، حجم، مدت",
      "dimensions": [
        "supplier",
        "item"
      ],
      "measures": [
        "volume",
        "price_per_unit",
        "start_date",
        "end_date"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "purchase_price_variance",
      "description": "انحراف قیمت خرید",
      "formula": "(قیمت واقعی - قیمت برنامه‌ریزی‌شده) / قیمت برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "item"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "purchase_price_variance"
    ],
    "period": "last_3_months"
  }
}

TOOL_OBSERVATION:
{
  "ppv_trend": [
    0.9,
    -1.0,
    1.4
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "contracts",
    "filters": {
      "period": "next_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "status": "داده ناقص",
  "available": [
    "ppv ۳ ماه اخیر"
  ],
  "missing": [
    "ترکیب قراردادها (ثابت/شناور)",
    "نرخ ارز پیش‌بینی",
    "قیمت جهانی مواد اولیه"
  ]
}

